oficial('examen_completos', {"exam_name": {"$in": [2012, "2012"]}, "question": "En la unidad coronaria se está administrando alteplasa a un paciente. La enfermera debe estar alerta a la aparición de:"}, {"option_3": "Trombloflebitis."}, "2012 fila 2260 (oficial 53)", false);
oficial('examen_completos', {"exam_name": {"$in": [2012, "2012"]}, "question": "¿Con qué onda del electrocardiograma coincide la descarga eléctrica en una cardioversión?:"}, {"question": "¿Con qué onda del electrocardiograma coincide la descarga eléctrica en una cardioversión?:", "option_1": "Es indiferente.", "option_2": "Con la onda T.", "option_3": "Siempre con la onda P.", "option_4": "En cualquier parte del segmento ST.", "option_5": "Con la onda R.", "answer": 5, "long_answer": "En la cardioversión eléctrica sincronizada el desfibrilador detecta el complejo QRS del paciente y libera la descarga coincidiendo con la onda R. El objetivo es evitar que el choque caiga sobre la onda T, que corresponde al periodo vulnerable de la repolarización ventricular: una descarga en ese momento puede desencadenar una fibrilación ventricular. Por eso no es indiferente el momento de la descarga, nunca debe coincidir con la onda T y tampoco se sincroniza con la onda P (actividad auricular) ni con cualquier punto del segmento ST, que forma parte de la fase de repolarización. Esto la diferencia de la desfibrilación, empleada en la fibrilación ventricular o la taquicardia ventricular sin pulso, en la que no hay complejos QRS organizados y la descarga se aplica de forma no sincronizada."}, "2012 fila 2266 (oficial 59)", false);
