oficial('examen_completos', {"exam_name": {"$in": [2012, "2012"]}, "question": {"$in": ["ETP está recibiendo el segundo ciclo de fármaco citostáticos, se queja de náuseas y está comenzando a rechazar los alimentos. ¿Cuál de las siguientes instrucciones incluiría en su plan de cuidados?:", "ETP está recibiendo el segundo ciclo de fármacos citostáticos, se queja de náuseas y está comenzando a rechazar los alimentos. ¿Cuál de las siguientes instrucciones incluiría en su plan de cuidados?:"]}}, {"question": "ETP está recibiendo el segundo ciclo de fármacos citostáticos, se queja de náuseas y está comenzando a rechazar los alimentos. ¿Cuál de las siguientes instrucciones incluiría en su plan de cuidados?:"}, "2012 fila 2304 (oficial 97)", false);
