oficial('examen_completos', {"exam_name": {"$in": [2012, "2012"]}, "question": {"$in": ["Según Prochaska y Di Clemente, una persona que se plantea dejar de fumar en los próximos 3 meses y está abierta a recibir información, se encuentra en la siguiente fase de cambio de conducta:      ", "Según Prochasca y Di Clemente, una persona que se plantea dejar de fumar en los próximos 3 meses y está abierta a recibir información, se encuentra en la siguiente fase de cambio de conducta:"]}}, {"question": "Según Prochasca y Di Clemente, una persona que se plantea dejar de fumar en los próximos 3 meses y está abierta a recibir información, se encuentra en la siguiente fase de cambio de conducta:", "option_1": "Precontemplación.", "option_2": "Contemplación.", "option_3": "Preparación.", "option_4": "Acción."}, "2012 fila 2324 (oficial 121)", false);
