oficial('examen_completos', {"exam_name": {"$in": [2014, "2014"]}, "question": {"$in": ["En las neuronas una vez que un potencial de acción ha comenzado, un segundo potencial de acción no puede ser disparado durante un breve espacio de tiempo, independientemente de la intensidad del estímulo aplicado. Este período de tiempo se conoce como:", "En las neuronas una vez que un potencial de acción ha comenzado, un segundo potencial de acción no puede ser disparado durante un breve espacio de tiempo, independientemente de la intensidad del estímulo aplicado. Este periodo de tiempo se conoce como:"]}}, {"question": "En las neuronas una vez que un potencial de acción ha comenzado, un segundo potencial de acción no puede ser disparado durante un breve espacio de tiempo, independientemente de la intensidad del estímulo aplicado. Este periodo de tiempo se conoce como:", "option_1": "Retraso sináptico."}, "2014 fila 1837 (oficial 3)", false);
oficial('examen_completos', {"exam_name": {"$in": [2014, "2014"]}, "question": {"$in": ["Según el modelo diagnóstico que se aporta ¿cuál es un enunciado correcto?: Intolerancia a la actividad (00092) \"Dominio 4: Actividad/Reposo\" \"Clase 4: Respuestas cardiovasculares/pulmonares\" Definición: Falta de energía fisiológica o psicológica suficiente para tolerar o completar las actividades diarias requeridas o deseadas. Características definitivas: Presión arterial anormal en respuesta a la actividad. Frecuencia cardíaca anormal en respuesta a la actividad. Cambios electrocardiográficos indicadores de arritmias. Disconfort por el esfuerzo. Disnea de esfuerzo. Expresa fatiga. Expresa debilidad. Factores relacionados: Reposo en cama. Debilidad generalizada. Desequilibrio entre aporte y demanda de oxígeno. Inmovilidad. Estilo de vida sedentario.", "Según el modelo diagnóstico que se aporta ¿cuál es un enunciado correcto?: Intolerancia a la actividad (00092) \"Dominio 4: Actividad/Reposo\" \"Clase 4: Respuestas cardiovasculares/pulmonares\" Definición: Falta de energía fisiológica o psicológica suficiente para tolerar o completar las actividades diarias requeridas o deseadas. Características definitorias: Presión arterial anormal en respuesta a la actividad. Frecuencia cardiaca anormal en respuesta a la actividad. Cambios electrocardiográficos indicadores de arritmias. Disconfort por el esfuerzo. Disnea de esfuerzo. Expresa fatiga. Expresa debilidad. Factores relacionados: Reposo en cama. Debilidad generalizada. Desequilibrio entre aporte y demanda de oxígeno. Inmovilidad. Estilo de vida sedentario."]}}, {"question": "Según el modelo diagnóstico que se aporta ¿cuál es un enunciado correcto?: Intolerancia a la actividad (00092) \"Dominio 4: Actividad/Reposo\" \"Clase 4: Respuestas cardiovasculares/pulmonares\" Definición: Falta de energía fisiológica o psicológica suficiente para tolerar o completar las actividades diarias requeridas o deseadas. Características definitorias: Presión arterial anormal en respuesta a la actividad. Frecuencia cardiaca anormal en respuesta a la actividad. Cambios electrocardiográficos indicadores de arritmias. Disconfort por el esfuerzo. Disnea de esfuerzo. Expresa fatiga. Expresa debilidad. Factores relacionados: Reposo en cama. Debilidad generalizada. Desequilibrio entre aporte y demanda de oxígeno. Inmovilidad. Estilo de vida sedentario.", "option_2": "Intolerancia a la actividad r/c insuficiencia cardiaca m/p debilidad generalizada."}, "2014 fila 1854 (oficial 35)", false);
