oficial('examen_completos', {"exam_name": {"$in": [2015, "2015"]}, "question": {"$in": ["La escala de Braden se utiliza en las primeras 24 horas de ingreso del paciente para evaluar el riesgo de úlceras por presión. Teniendo en cuenta esto, señale qué puntuación tendría una persona que tiene alto riesgo de sufrir úlceras por presión:", "La escala de Braden se utiliza en las primeras 24 horas de ingreso del paciente para evaluar el riesgo de ulceras por presión. Teniendo en cuenta esto, señale qué puntuación tendría una persona que tiene alto riesgo de sufrir ulceras por presión:"]}}, {"question": "La escala de Braden se utiliza en las primeras 24 horas de ingreso del paciente para evaluar el riesgo de ulceras por presión. Teniendo en cuenta esto, señale qué puntuación tendría una persona que tiene alto riesgo de sufrir ulceras por presión:"}, "2015 fila 1705 (oficial 112)", false);
