oficial('examen_completos', {"exam_name": {"$in": [2015, "2015"]}, "question": {"$in": ["¿Qué teoría del envejecimiento ejemplifica un ebanista de 76 años jubilado que mantiene interés por mantenerse activo y colaborar con el colegio y la parroquia del barrio...?:", "¿Qué teoría del envejecimiento ejemplifica un ebanista de 76 años jubilado que mantiene interés por mantenerse activo y colaborar con el colegio y la parroquia del barrio en los trabajos de mantenimiento del mobiliario, puertas, piezas de madera para los niños, etc.?:"]}}, {"question": "¿Qué teoría del envejecimiento ejemplifica un ebanista de 76 años jubilado que mantiene interés por mantenerse activo y colaborar con el colegio y la parroquia del barrio en los trabajos de mantenimiento del mobiliario, puertas, piezas de madera para los niños, etc.?:"}, "2015 fila 1782 (oficial 191)", false);
oficial('examen_completos', {"exam_name": {"$in": [2015, "2015"]}, "question": {"$in": ["Un anciano se dirige a la enfermera refiriendo: \"me siento desbordado con el tratamiento que me han puesto; no sé si voy a ser capaz de seguirlo\"...", "Un anciano se dirige a la enfermera refiriendo: “me siento desbordado con el tratamiento que me han puesto; no sé si voy a ser capaz de seguirlo”. De las siguientes respuestas de la enfermera ¿Cuál constituye el mejor ejemplo de comunicación terapéutica?:"]}}, {"question": "Un anciano se dirige a la enfermera refiriendo: “me siento desbordado con el tratamiento que me han puesto; no sé si voy a ser capaz de seguirlo”. De las siguientes respuestas de la enfermera ¿Cuál constituye el mejor ejemplo de comunicación terapéutica?:"}, "2015 fila 1783 (oficial 192)", false);
