oficial('examen_completos', {"exam_name": {"$in": [2016, "2016"]}, "question": "Respecto a las Desigualdades en Salud es cierto que:"}, {"option_1": "Numerosos estudios científicos muestran que las desigualdades en salud son responsables de un exceso de morbimortalidad similar a la mayoría de los factores de riesgo de enfermar conocidos.", "option_2": "Los distintos ejes de desigualdad que determinan jerarquías de poder en la sociedad son la clase social, el género, la edad, la etnia o la raza y el territorio."}, "2016 fila 1374 (oficial 1)", false);
