oficial('examen_completos', {"exam_name": {"$in": [2016, "2016"]}, "question": {"$in": ["Según American Heart Association sobre RCP, ¿cuál de las siguientes afirmaciones NO es correcta?:", "Según las últimas recomendaciones de la Amercian Heart Association sobre RCP, ¿cuál de las siguientes afirmaciones NO es correcta?:"]}}, {"question": "Según las últimas recomendaciones de la Amercian Heart Association sobre RCP, ¿cuál de las siguientes afirmaciones NO es correcta?:", "option_1": "En el caso de un paro cardiaco en una víctima adulta con un testigo presencial y con disponibilidad inmediata de un DEA (Desfibrilador Externo Automático), es razonable que se utilice el desfibrilador lo antes posible.", "option_4": "Se recomienda encarecidamente el uso de dispositivos de compresión torácica mecánicos frente a las compresiones torácicas en pacientes con paro cardiaco."}, "2016 fila 1439 (oficial 69)", false);
