oficial('examen_completos', {"exam_name": {"$in": [2017, "2017"]}, "question": {"$in": ["Un anestésico local está indicado en el tratamiento de las arritmias ventriculares, como aquellas que resultan de un infarto agudo de miocardio, toxicidad por digital, cirugía cardíaca o cateterismo cardíaco. Se trata de:", "Un anestésico local está indicado en el tratamiento de las arritmias ventriculares, como aquellas que resultan de un infarto agudo de miocardio, toxicidad por digital, cirugía cardiaca o cateterismo cardíaco. Se trata de:"]}}, {"question": "Un anestésico local está indicado en el tratamiento de las arritmias ventriculares, como aquellas que resultan de un infarto agudo de miocardio, toxicidad por digital, cirugía cardiaca o cateterismo cardíaco. Se trata de:", "option_4": "Procaína."}, "2017 fila 1257 (oficial 118)", false);
