oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": {"$in": ["Las preguntas clínicas pueden clasificarse según el dominio clínico al que correspondan: ¿Cuál de las siguientes opciones NO es una categoría agrupación de dicho dominio?:", "Las preguntas clínicas pueden clasificarse según el dominio clínico al que correspondan. ¿Cuál de las siguientes opciones NO es una categoría de agrupación de dicho dominio?:"]}}, {"question": "Las preguntas clínicas pueden clasificarse según el dominio clínico al que correspondan. ¿Cuál de las siguientes opciones NO es una categoría de agrupación de dicho dominio?:"}, "2018 fila 959 (oficial 49)", false);
