oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": {"$in": ["La clasificación ASA (American Society of Anesthesiology), se utiliza para estimar el riesgo del paciente. Según esta clasificación, un anestesia para los diferentes estados del paciente, tendrá Clase II cuando:", "La clasificación ASA (American Society of Anesthesiology), se utiliza para estimar el riesgo que plantea la anestesia para los diferentes estados del paciente. Según esta clasificación, un paciente tendrá Clase II cuando:"]}}, {"question": "La clasificación ASA (American Society of Anesthesiology), se utiliza para estimar el riesgo que plantea la anestesia para los diferentes estados del paciente. Según esta clasificación, un paciente tendrá Clase II cuando:"}, "2018 fila 1009 (oficial 99)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": "Señale la respuesta correcta respecto de la Prueba de Marcha de los 6 minutos o Test de los 6 minutos (PM6M):"}, {"option_1": "Mide la distancia máxima que un individuo puede recorrer caminado durante seis minutos, con intervalos de caminata-descanso de 1 minuto hasta completar los 6 minutos totales (caminar 1 minuto y descansar otro, hasta completar 6 minutos)."}, "2018 fila 1013 (oficial 103)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": {"$in": ["El American College of Cardiology (ACC) y la American Heart Association (AHA) han publicado recientemente la guía para la prevención, detección, evaluación y tratamiento de la hipertensión arterial (HTA) en adultos. El punto más controvertido es el nuevo umbral diagnóstico asignado a la situación de HTA, que en la Guía queda definida como aquella presión arterial igual o superior a:", "El American College of Cardiology (ACC) y la American Heart Association (AHA) han publicado recientemente la guía para la prevención, detección, evaluación y tratamiento de la hipertensión arterial (HTA) en adultos. El punto más controvertido es el nuevo umbral diagnostico asignado a la situación de HTA, que en la Guía queda definida como aquella presión arterial igual o superior a:"]}}, {"question": "El American College of Cardiology (ACC) y la American Heart Association (AHA) han publicado recientemente la guía para la prevención, detección, evaluación y tratamiento de la hipertensión arterial (HTA) en adultos. El punto más controvertido es el nuevo umbral diagnostico asignado a la situación de HTA, que en la Guía queda definida como aquella presión arterial igual o superior a:"}, "2018 fila 1014 (oficial 104)", false);
