oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": {"$in": ["¿Cuáles de las siguientes modificaciones en la dieta tiene mayor efecto de descenso en la reducción de colesterol total y LDL?:", "¿Cuáles de las siguientes modificaciones en la dieta tiene mayor magnitud de efecto en la reducción de colesterol total y colesterol LDL?:"]}}, {"question": "¿Cuáles de las siguientes modificaciones en la dieta tiene mayor magnitud de efecto en la reducción de colesterol total y colesterol LDL?:"}, "2018 fila 1086 (oficial 177)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": "¿Cuál de los siguientes síntomas caracteriza el Delirium? Situación que padece hasta el 80% de los pacientes con una enfermedad avanzada y/o en fase final de la vida. Indique la opción correcta:"}, {"option_3": "Habla inapropiada, inconsecuente o variar de la verborrea al silencio, desorientación temporo-espacial, desatención, ilusiones y alucinaciones."}, "2018 fila 1092 (oficial 184)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": "¿Cuál sería el orden adecuado de la valoración del cuadro doloroso y de la situación clínica del individuo, antes de iniciar el tratamiento analgésico de un paciente en cuidados paliativos? Indique la opción correcta:"}, {"option_2": "Preguntar al paciente por el dolor; cuantificar el dolor mediante alguna escala (McGill o EVA); realizar una historia del dolor; realizar una exploración física completa; clasificar el dolor; administrar el tratamiento analgésico adecuado; evaluar la respuesta al tratamiento analgésico."}, "2018 fila 1093 (oficial 185)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": "Un elemento clave para una comunicación eficaz es saber escuchar. Sobre la escucha activa, NO es cierto que:"}, {"option_3": "El silencio disfuncional se produce cuando el entrevistador presenta una reactividad alta.", "long_answer": "La escucha activa es una habilidad básica de la entrevista clínica y la afirmación que no es cierta es la referida al silencio. El silencio funcional es una técnica útil en la que el profesional deja un tiempo sin intervenir para que el paciente piense y continúe expresándose; se asocia a una reactividad baja. Cuando el entrevistador tiene una reactividad alta, es decir, interrumpe o responde de inmediato, lo que se produce es la ausencia de silencios útiles, no un silencio disfuncional, por lo que el enunciado relaciona conceptos de forma errónea. Las demás afirmaciones son correctas: la escucha activa está recogida en la NIC como intervención 4920; la clarificación ayuda a contrastar lo que el paciente ha querido decir y aclarar ideas vagas o confusas; y el sumario permite ordenar las ideas, revisar progresos y obtener confirmación del paciente."}, "2018 fila 1096 (oficial 188)", false);
oficial('examen_completos', {"exam_name": {"$in": [2018, "2018"]}, "question": {"$in": ["C.M.B. es un varón de 40 años diagnosticado de trastorno bipolar en terapia de mantenimiento con carbonato de litio desde hace 3 años que acude a la consulta de enfermería del Centro de Salud Mental. Señale la respuesta correcta en relación al tratamiento con carbono de litio:", "C.M.B. es un varón de 40 años diagnosticado de trastorno bipolar en terapia de mantenimiento con carbonato de litio desde hace 3 años que acude a la consulta de enfermería del Centro de Salud Mental. Señale la respuesta correcta en relación al tratamiento con carbonato de litio:"]}}, {"question": "C.M.B. es un varón de 40 años diagnosticado de trastorno bipolar en terapia de mantenimiento con carbonato de litio desde hace 3 años que acude a la consulta de enfermería del Centro de Salud Mental. Señale la respuesta correcta en relación al tratamiento con carbonato de litio:"}, "2018 fila 1099 (oficial 191)", false);
