oficial('examen_completos', {"exam_name": {"$in": [2019, "2019"]}, "question": {"$in": ["Según la normativa de la Sociedad Española de Neumología y Cirugía Torácica (SEPAR), señale a qué patrón espirométrico corresponden los siguientes resultados de una prueba de función respiratoria: FVC: 2380 cc (71%), FEV1: 1890 cc (76%), FEV1/FVC: 79,41%:", "Según la normativa de la Sociedad Española de Neumología y Cirugía Torácica (SEPAR), señale a qué patrón espirométrico corresponden los siguientes resultados de una prueba de función respiratoria: FVC: 2380 cc (71%); FEV1: 1890 cc (76%), FEV1/FVC: 79,41%:"]}}, {"question": "Según la normativa de la Sociedad Española de Neumología y Cirugía Torácica (SEPAR), señale a qué patrón espirométrico corresponden los siguientes resultados de una prueba de función respiratoria: FVC: 2380 cc (71%); FEV1: 1890 cc (76%), FEV1/FVC: 79,41%:"}, "2019 fila 750 (oficial 21)", false);
