oficial('examen_completos', {"exam_name": {"$in": [2019, "2019"]}, "question": "De las tres etapas en que se divide el shock (compensatoria, progresiva e irreversible), ¿cuáles son las características de la Respiración, Frecuencia Cardiaca (FC) y Tensión Arterial (TA) que corresponden a la etapa progresiva?:"}, {"option_1": "Respiración rápida y con estertores; FC > 150 lpm; TA sistólica < 90 mmHg.", "option_2": "Frecuencia respiratoria (FR) > 20 respiraciones por minuto; FC > 100 lpm; TA Normal.", "option_3": "Respiración que requiere intubación y ventilación; FC errática; TA que requiere apoyo farmacológico.", "option_4": "Respiración: FR normal; FC > 180 lpm; TA sistólica > 180 mmHg."}, "2019 fila 775 (oficial 46)", false);
