oficial('examen_completos', {"exam_name": {"$in": [2019, "2019"]}, "question": "Atendido a la siguiente pregunta clínica estructurada en formato “PICO”: ¿Se deben recomendar los programas educativos estructurados dirigidos a personas con diabetes mellitus tipo 1 y a sus familiares?, identifique cuál sería el componente clave INTERVENCIÓN:"}, {"option_3": "Autocontrol de la enfermedad: alimentación, ejercicio físico, cuidado de los pies, abandono control de la glucemia; reducción de enfermedad cardiovascular; prevención/reducción de visitas a urgencias, mejoría en calidad de vida, reducción de la mortalidad, reducción del hábito de fumar."}, "2019 fila 883 (oficial 156)", false);
