oficial('examen_completos', {"exam_name": {"$in": [2020, "2020"]}, "question": {"$in": ["El indice de consumo acumulado de tabaco (índice paquetes-año) es el resultado de:", "El índice de consumo acumulado de tabaco (índice paquetes-año), es el resultado de:"]}}, {"question": "El índice de consumo acumulado de tabaco (índice paquetes-año), es el resultado de:", "option_1": "Multiplicar el número de cigarrillos que fuma al día por 20 y dividido entre los años que lleva fumando.", "option_2": "Multiplicar el número de cigarrillos que fuma al día por los años que lleva fumando y dividido entre 20.", "option_3": "Multiplicar el número de años que lleva fumando por 20, dividido entre el número de cigarrillos que fuma al día.", "option_4": "Multiplicar el número de cigarrillos que fuma al día por los años que lleva fumando y sumar 20."}, "2020 fila 648 (oficial 97)", false);
