oficial('examen_completos', {"exam_name": {"$in": [2020, "2020"]}, "question": {"$in": ["Un paciente lleva 15 minutos conectado monitor de hemodiálisis. Avisa porque siente sudoración y se encuentra mareado. Su tensión arterial de inicio era: 140/80 mmHg. Se toma Ia tensión de nuevo tiene 85/50 mmHg: Su ganancia interdiálisis es de 2Kg y tiene pautada 4 horas de sesión. Con estos datos, ¿cuál puede ser el origen de la hipotensión que presenta?:", "Un paciente lleva 15 minutos conectado a su monitor de hemodiálisis. Avisa porque siente sudoración y se encuentra mareado. Su tensión arterial de inicio era: 140/80 mmHg. Se toma la tensión de nuevo y tiene 85/50 mmHg. Su ganancia interdiálisis es de 2Kg y tiene pautada 4 horas de sesión. Con estos datos, ¿cuál puede ser el origen de la hipotensión que presenta?:"]}}, {"question": "Un paciente lleva 15 minutos conectado a su monitor de hemodiálisis. Avisa porque siente sudoración y se encuentra mareado. Su tensión arterial de inicio era: 140/80 mmHg. Se toma la tensión de nuevo y tiene 85/50 mmHg. Su ganancia interdiálisis es de 2Kg y tiene pautada 4 horas de sesión. Con estos datos, ¿cuál puede ser el origen de la hipotensión que presenta?:", "option_1": "Ganancia interdiálisis elevada.", "option_3": "Desequilibrio hidroelectrolítico."}, "2020 fila 652 (oficial 101)", false);
