oficial('examen_completos', {"exam_name": {"$in": [2020, "2020"]}, "question": {"$in": ["Según las guías sobre el ejercicio y la práctica deportiva de la Sociedad Europea de Cardiología, ¿qué recomendación deportiva con evidencia I-A dará a un paciente hipertenso bien controlado?:", "Según las guías sobre el ejercicio y la práctica deportiva en los pacientes cardiovasculares de la Sociedad Europea de Cardiología, ¿qué recomendación deportiva con evidencia I-A se dará a un paciente hipertenso bien controlado?:"]}}, {"question": "Según las guías sobre el ejercicio y la práctica deportiva en los pacientes cardiovasculares de la Sociedad Europea de Cardiología, ¿qué recomendación deportiva con evidencia I-A se dará a un paciente hipertenso bien controlado?:", "option_1": "Al menos 150 minutos semanales de ejercicio de intensidad moderada, o 75 minutos semanales de intensidad vigorosa, o una combinación equivalente.", "option_3": "Realizará ejercicios de fuerza, coordinación y equilibrio, al menos 2 días a la semana.", "option_4": "Realizará ejercicios de resistencia al menos 3 veces por semana, además de ejercicio aeróbico moderado o vigoroso (al menos 30 minutos), de 5 a 7 veces por semana."}, "2020 fila 663 (oficial 112)", false);
