oficial('examen_completos', {"exam_name": {"$in": [2020, "2020"]}, "question": {"$in": ["En la evaluación de los signos y síntomas más prevalentes atribuibles a la ulcera de etiología venosa, NO se encuentra habitualmente:", "En la evaluación de los signos y síntomas más prevalentes atribuibles a la úlcera de etiología venosa, NO se encuentra habitualmente:"]}}, {"question": "En la evaluación de los signos y síntomas más prevalentes atribuibles a la úlcera de etiología venosa, NO se encuentra habitualmente:", "option_4": "Tejido periulceroso con signos de insuficiencia venosa crónica avanzada: pigmentación, eccema y lipodermatoesclerosis, entre otros."}, "2020 fila 697 (oficial 148)", false);
oficial('examen_completos', {"exam_name": {"$in": [2020, "2020"]}, "question": "La alimentación en el paciente con enfermedad renal crónica (ERC) es un punto clave en el desarrollo de la enfermedad. Indique cuál de las siguientes afirmaciones es INCORRECTA:"}, {"option_1": "Los principales motivos para el control dietético en los pacientes con ERC son: minimizar el riesgo de uremia, hiperpotasemia, hiperfosfatemia, hipercalcemia, hipervolemia, anemia y acidosis metabólica.", "option_4": "En el paciente con ERC avanzada es importante dar indicaciones sobre cómo consumir las frutas y verduras, teniendo en cuenta además de una selección adecuada unas correctas técnicas de cocinado: corte fino, eliminación del agua tras ebullición, doble cocción, entre otras."}, "2020 fila 698 (oficial 149)", false);

